import{_ as l,l as o,o as e,c as s,v as t,p as n,x as r,d as p,i as c,S as d}from"./chunks/framework.InCnrqk-.js";const u=JSON.parse('{"title":"MVCC","description":"","frontmatter":{"title":"MVCC","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/mvcc.md","filePath":"cs/mvcc.md","lastUpdated":1789023840000}'),h={name:"cs/mvcc.md"};function m(E,a,_,A,C,B){const i=o("Mermaid");return e(),s("div",null,[a[1]||(a[1]=t('<h1 id="mvcc" tabindex="-1">MVCC <a class="header-anchor" href="#mvcc" aria-label="Permalink to &quot;MVCC&quot;">​</a></h1><div class="epigraph"><p>写出新版本而不原地覆盖；读去取自己快照里可见的那一版，读与写不必抢同一把锁。</p><footer>—— 据 Reed, Naming and Synchronization in a Decentralized Computer System, 1978；Bernstein 对多版本调度的整理</footer></div><p><a href="/cs/strict-2pl">上一课</a>用严格两阶段锁保证可串行，读也要加 S。本课不重讲锁点。缺口是：只读事务被写阻塞，或写被长查询挡住。多版本并发控制让写创建新版本，读按时间戳或快照选可见版本，读锁可以去掉或大大减弱。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>2PL 的 S 与 X 不兼容，分析查询会挡住更新。缺口不是放弃隔离，而是给每个写一个版本号（事务 id、时间戳），可见性函数回答「这一读能看见哪一版」。快照隔离（SI）是广泛实现：事务开始时钉一个快照，读都来自该快照，写冲突在提交时用写集检测。</p><p><span class="marginnote">SI 避免脏读、不可重复读与部分幻象，但允许写偏斜：两个事务读同一快照、写不同行，各自提交，串行下不可能同时成立。那是后课隔离级别要命名的异常。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>每行带创建/删除版本。读不阻塞写；写若与未提交或快照后的版本冲突，则 abort 或等待。垃圾回收删除对所有活跃快照都不可见的旧版。本课不把 SSI（可串行快照隔离）的冲突检测写完，只锁定：版本 + 可见性是与锁并列的实现轴。</p>',8)),(e(),n(d,null,{default:r(()=>[c(i,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20W%5B%22%E5%86%99%22%5D%20--%3E%20VER%5B%22%E6%96%B0%E7%89%88%E6%9C%AC%22%5D%0A%20%20R%5B%22%E8%AF%BB%22%5D%20--%3E%20VIS%5B%22%E5%BF%AB%E7%85%A7%E5%8F%AF%E8%A7%81%E6%80%A7%22%5D%0A%20%20VER%20--%3E%20GC%5B%22%E5%9B%9E%E6%94%B6%E6%97%A7%E7%89%88%22%5D%0A%20%20VIS%20--%3E%20ISO%5B%22%E5%90%8E%E8%AF%BE%3A%20%E9%9A%94%E7%A6%BB%E7%BA%A7%E5%88%AB%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[p(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>WAL 仍记录什么变了；版本是并发的表示，不是另一种恢复。回滚可以只是标该版本不可见。索引必须指向「当前」版本或带版本的项，B+ 叶上的空间与清理成为新的代价——与<a href="/cs/page-slot">页与槽</a>的空间回收相接。长只读快照会拖住 GC，这是 MVCC 的资源边界。</p><p>写写冲突仍要检测或等待；「读不阻塞写」不等于「写不冲突」。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>MVCC 不是自动可串行。SI ≠ 冲突可串行。本课也不把「无锁」写成事实：写写仍要检测，字典结构本身仍要闩锁（latch），那是物理短锁，不是 2PL 的事务锁。</p><p>只读事务可以拿一个旧快照一直读，写者前进；这是分析负载的常见配置，代价是旧版本堆积。后课默认：引擎可以锁、可以版本、可以混合（写锁 + 读快照）；用户看见的强度用隔离级别与异常来谈，而不是用内部版本号。</p><p>快照是时间上的切面，不是另一份数据库。写仍要落 WAL；版本只回答「读看见谁」，不替代提交记录。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li><p>长快照拖住垃圾回收，是 MVCC 的空间账单，不是免费的非阻塞读。</p></li><li><p>后课用异常名字把 SI 与可串行的差额说给应用听。</p></li><li><p>2PL 让读写互斥；MVCC 用版本让读走快照。</p></li><li><p>可见性函数是隔离的实现；SI 仍可能写偏斜。</p></li><li><p>用户侧档位（读已提交、可重复读、可串行）是后课缺口。</p></li><li><p>出处：Reed, 1978；Berenson et al., 1995；Bernstein 多版本章节。</p></li></ul>',9))])}const f=l(h,[["render",m]]);export{u as __pageData,f as default};
